INSERT OR IGNORE INTO site_data(id,data,updated_at) VALUES('beliefs.beliefs','[{"id":1,"key":"dios-trino","number":"01","title":"Dios Trino","description":"Creemos en un solo Dios verdadero, eterno y soberano, manifestado como Padre, Hijo y Espíritu Santo, perfecto en poder, sabiduría y bondad.","icon":"scroll","verses":[{"ref":"Mateo 28:19","version":"RVR1960","text":"Por tanto, id, y haced discípulos a todas las naciones, bautizándolos en el nombre del Padre, y del Hijo, y del Espíritu Santo;"},{"ref":"2 Corintios 13:14","version":"RVR1960","text":"La gracia del Señor Jesucristo, el amor de Dios, y la comunión del Espíritu Santo sean con todos vosotros. Amén."},{"ref":"Deuteronomio 6:4","version":"RVR1960","text":"Oye, Israel: Jehová nuestro Dios, Jehová uno es."}]},{"id":2,"key":"jesucristo","number":"02","title":"Jesucristo","description":"Creemos en Jesucristo como Hijo de Dios y único Salvador de la humanidad, quien murió y resucitó, y que intercede ante el Padre por quienes le invocan en espíritu y en verdad.","icon":"scroll","verses":[{"ref":"Juan 14:6","version":"RVR1960","text":"Jesús le dijo: Yo soy el camino, y la verdad, y la vida; nadie viene al Padre, sino por mí."},{"ref":"Hechos 4:12","version":"RVR1960","text":"Y en ningún otro hay salvación; porque no hay otro nombre bajo el cielo, dado a los hombres, en que podamos ser salvos."},{"ref":"Romanos 8:34","version":"RVR1960","text":"¿Quién es el que condenará? Cristo es el que murió; más aun, el que también resucitó, el que además está a la diestra de Dios, el que también intercede por nosotros."}]},{"id":3,"key":"santas-escrituras","number":"03","title":"Las Santas Escrituras","description":"Creemos en la autoridad de la Santa Biblia como Palabra inspirada por Dios, compuesta por los sesenta y seis libros canónicos del Antiguo y del Nuevo Testamento.","icon":"scroll","verses":[{"ref":"2 Timoteo 3:16","version":"RVR1960","text":"Toda la Escritura es inspirada por Dios, y útil para enseñar, para redargüir, para corregir, para instruir en justicia,"},{"ref":"2 Pedro 1:21","version":"RVR1960","text":"Porque nunca la profecía fue traída por voluntad humana, sino que los santos hombres de Dios hablaron siendo inspirados por el Espíritu Santo."},{"ref":"Salmo 119:105","version":"RVR1960","text":"Lámpara es a mis pies tu palabra, Y lumbrera a mi camino."}]},{"id":4,"key":"bautismo-y-santa-cena","number":"04","title":"Bautismo y Santa Cena","description":"Reconocemos como ordenanzas divinas el Bautismo de Agua por Aspersión y la Santa Cena, como testimonios visibles de la obra redentora de Cristo.","icon":"scroll","verses":[{"ref":"Mateo 28:19","version":"RVR1960","text":"Por tanto, id, y haced discípulos a todas las naciones, bautizándolos en el nombre del Padre, y del Hijo, y del Espíritu Santo;"},{"ref":"1 Corintios 11:23-26","version":"RVR1960","text":"Porque yo recibí del Señor lo que también os he enseñado: Que el Señor Jesús, la noche que fue entregado, tomó pan; y habiendo dado gracias, lo partió, y dijo: Tomad, comed; esto es mi cuerpo que por vosotros es partido; haced esto en memoria de mí. Asimismo tomó también la copa, después de haber cenado, diciendo: Esta copa es el nuevo pacto en mi sangre; haced esto todas las veces que la bebiereis, en memoria de mí. Así, pues, todas las veces que comiereis este pan, y bebiereis esta copa, la muerte del Señor anunciáis hasta que él venga."},{"ref":"Marcos 16:16","version":"RVR1960","text":"El que creyere y fuere bautizado, será salvo; mas el que no creyere, será condenado."}]},{"id":5,"key":"bautismo-del-espiritu-santo","number":"05","title":"Bautismo del Espíritu Santo","description":"Creemos en el Bautismo del Espíritu Santo como una obra poderosa de Dios, regeneradora y transformadora, que produce gozo, consagración y vida nueva.","icon":"scroll","verses":[{"ref":"Hechos 1:8","version":"RVR1960","text":"Pero recibiréis poder, cuando haya venido sobre vosotros el Espíritu Santo, y me seréis testigos en Jerusalén, en toda Judea, en Samaria, y hasta lo último de la tierra."},{"ref":"Hechos 2:4","version":"RVR1960","text":"Y fueron todos llenos del Espíritu Santo, y comenzaron a hablar en otras lenguas, según el Espíritu les daba que hablasen."},{"ref":"Tito 3:5-6","version":"RVR1960","text":"nos salvó, no por obras de justicia que nosotros hubiéramos hecho, sino por su misericordia, por el lavamiento de la regeneración y por la renovación en el Espíritu Santo, el cual derramó en nosotros abundantemente por Jesucristo nuestro Salvador,"}]},{"id":6,"key":"resurreccion","number":"06","title":"Resurrección","description":"Creemos en la resurrección de los muertos y en la glorificación de los redimidos, conforme a la victoria de Jesucristo resucitado.","icon":"scroll","verses":[{"ref":"1 Corintios 15:20-22","version":"RVR1960","text":"Mas ahora Cristo ha resucitado de los muertos; primicias de los que durmieron es hecho. Porque por cuanto la muerte entró por un hombre, también por un hombre la resurrección de los muertos. Porque así como en Adán todos mueren, también en Cristo todos serán vivificados."},{"ref":"Juan 11:25","version":"RVR1960","text":"Le dijo Jesús: Yo soy la resurrección y la vida; el que cree en mí, aunque esté muerto, vivirá."},{"ref":"Filipenses 3:20-21","version":"RVR1960","text":"Mas nuestra ciudadanía está en los cielos, de donde también esperamos al Salvador, al Señor Jesucristo; el cual transformará el cuerpo de la humillación nuestra, para que sea semejante al cuerpo de la gloria suya, por el poder con el cual puede también sujetar a sí mismo todas las cosas."}]},{"id":7,"key":"segunda-venida","number":"07","title":"Segunda Venida de Cristo","description":"Creemos en la segunda venida de Cristo a la tierra, de manera inminente, personal y premilenial, conforme a la esperanza bienaventurada de la Iglesia.","icon":"scroll","verses":[{"ref":"1 Tesalonicenses 4:16-17","version":"RVR1960","text":"Porque el Señor mismo con voz de mando, con voz de arcángel, y con trompeta de Dios, descenderá del cielo; y los muertos en Cristo resucitarán primero. Luego nosotros los que vivimos, los que hayamos quedado, seremos arrebatados juntamente con ellos en las nubes para recibir al Señor en el aire, y así estaremos siempre con el Señor."},{"ref":"Tito 2:13","version":"RVR1960","text":"aguardando la esperanza bienaventurada y la manifestación gloriosa de nuestro gran Dios y Salvador Jesucristo,"},{"ref":"Apocalipsis 20:1-6","version":"RVR1960","text":"Y vi a un ángel que descendía del cielo, con la llave del abismo, y una gran cadena en la mano. Y prendió al dragón, la serpiente antigua, que es el diablo y Satanás, y lo ató por mil años; y lo arrojó al abismo, y lo encerró, y puso su sello sobre él, para que no engañase más a las naciones, hasta que fuesen cumplidos mil años; y después de esto debe ser desatado por un poco de tiempo. Y vi tronos, y se sentaron sobre ellos los que recibieron facultad de juzgar; y vi las almas de los decapitados por causa del testimonio de Jesús y por la palabra de Dios, los que no habían adorado a la bestia ni a su imagen, y que no recibieron la marca en sus frentes ni en sus manos; y vivieron y reinaron con Cristo mil años. Pero los otros muertos no volvieron a vivir hasta que se cumplieron mil años. Esta es la primera resurrección. Bienaventurado y santo el que tiene parte en la primera resurrección; la segunda muerte no tiene potestad sobre éstos, sino que serán sacerdotes de Dios y de Cristo, y reinarán con él mil años."}]},{"id":8,"key":"justificacion-por-la-fe","number":"08","title":"Justificación por la Fe","description":"Creemos en la justificación por la fe en Jesucristo y no por las obras de la ley, afirmando que la salvación descansa únicamente en la obra de Cristo.","icon":"scroll","verses":[{"ref":"Romanos 3:28","version":"RVR1960","text":"Concluimos, pues, que el hombre es justificado por fe sin las obras de la ley."},{"ref":"Gálatas 2:16","version":"RVR1960","text":"sabiendo que el hombre no es justificado por las obras de la ley, sino por la fe de Jesucristo, nosotros también hemos creído en Jesucristo, para ser justificados por la fe de Cristo y no por las obras de la ley, por cuanto por las obras de la ley nadie será justificado."},{"ref":"Efesios 2:8-9","version":"RVR1960","text":"Porque por gracia sois salvos por medio de la fe; y esto no de vosotros, pues es don de Dios; no por obras, para que nadie se gloríe."}]},{"id":9,"key":"salvacion-por-gracia","number":"09","title":"Salvación por Gracia","description":"Creemos que la salvación es otorgada por gracia de nuestro Señor Jesucristo, y que el creyente debe perseverar en Cristo con la ayuda del Espíritu Santo.","icon":"scroll","verses":[{"ref":"Efesios 2:8","version":"RVR1960","text":"Porque por gracia sois salvos por medio de la fe; y esto no de vosotros, pues es don de Dios;"},{"ref":"Juan 10:27-29","version":"RVR1960","text":"Mis ovejas oyen mi voz, y yo las conozco, y me siguen, y yo les doy vida eterna; y no perecerán jamás, ni nadie las arrebatará de mi mano. Mi Padre que me las dio, es mayor que todos, y nadie las puede arrebatar de la mano de mi Padre."},{"ref":"Colosenses 1:23","version":"RVR1960","text":"si en verdad permanecéis fundados y firmes en la fe, y sin moveros de la esperanza del evangelio que habéis oído, el cual se predica en toda la creación que está debajo del cielo; del cual yo Pablo fui hecho ministro."}]},{"id":10,"key":"matrimonio","number":"10","title":"Matrimonio","description":"Reconocemos el matrimonio como una bendición establecida por Dios entre un hombre y una mujer, conforme a las Sagradas Escrituras.","icon":"scroll","verses":[{"ref":"Génesis 2:24","version":"RVR1960","text":"Por tanto, dejará el hombre a su padre y a su madre, y se unirá a su mujer, y serán una sola carne."},{"ref":"Mateo 19:4-6","version":"RVR1960","text":"Él, respondiendo, les dijo: ¿No habéis leído que el que los hizo al principio, varón y hembra los hizo, y dijo: Por esto el hombre dejará padre y madre, y se unirá a su mujer, y los dos serán una sola carne? Así que no son ya más dos, sino una sola carne; por tanto, lo que Dios juntó, no lo separe el hombre."},{"ref":"Efesios 5:31","version":"RVR1960","text":"Por esto dejará el hombre a su padre y a su madre, y se unirá a su mujer, y los dos serán una sola carne."}]}]','2026-10-05T00:00:00Z');
